import tempfile
import torch
from torch.utils.data import DataLoader, TensorDataset
import lightning.pytorch as pl
from lightning.pytorch import Trainer
from lightning.pytorch.callbacks import ModelCheckpoint, ProgressBar

trainer = Trainer(enable_checkpointing=False, enable_progress_bar=False, logger=False, barebones=True)
assert trainer.checkpoint_callback is None
assert trainer.progress_bar_callback is None

class BoringModel(pl.LightningModule):
    def __init__(self):
        super().__init__()
        self.layer = torch.nn.Linear(2, 1)
    def forward(self, x):
        return self.layer(x)
    def training_step(self, batch, batch_idx):
        x, y = batch
        return torch.nn.functional.mse_loss(self(x), y)
    def validation_step(self, batch, batch_idx):
        x, y = batch
        self.log('val_loss', torch.nn.functional.mse_loss(self(x), y))
    def test_step(self, batch, batch_idx):
        x, y = batch
        self.log('test_loss', torch.nn.functional.mse_loss(self(x), y))
    def predict_step(self, batch, batch_idx, dataloader_idx=0):
        x, y = batch
        return self(x)
    def configure_optimizers(self):
        return torch.optim.SGD(self.parameters(), lr=0.1)

loader = DataLoader(TensorDataset(torch.randn(4,2), torch.randn(4,1)), batch_size=2)
model = BoringModel()
trainer = Trainer(max_epochs=1, limit_train_batches=1, limit_val_batches=1, limit_test_batches=1, limit_predict_batches=1, enable_checkpointing=False, enable_progress_bar=False, logger=False)
trainer.fit(model, loader, loader)
assert isinstance(trainer.validate(dataloaders=loader), list)
assert isinstance(trainer.test(dataloaders=loader), list)
preds = trainer.predict(dataloaders=loader)
assert preds and isinstance(preds, list)
with tempfile.NamedTemporaryFile(suffix='.ckpt') as f:
    trainer.save_checkpoint(f.name)
    ckpt = torch.load(f.name, weights_only=False)
    for key in ['epoch', 'global_step', 'pytorch-lightning_version', 'state_dict', 'loops', 'callbacks', 'optimizer_states', 'lr_schedulers']:
        assert key in ckpt, key
print('smoke ok')
